// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzzed params: an arbitrary caller address and an arbitrary value v
    // We fuzz an address to act as `from`, and a uint256 v that goes through to the inner calls.
    function testFuzz_property(address caller, uint256 v) public {
        // Keep domain wide; ensure caller is non-zero to be a meaningful caller
        vm.assume(caller != address(0));

        // Prepare an empty _tos array (this is the deciding input: empty arrays should cause revert in reference)
        address[] memory tos = new address[](0);

        // Call c.transfer from `caller`. The reference MUST revert for empty _tos; the mutant may not.
        bool ok;
        try c.transfer(caller, address(0x1234), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // Assert: for all inputs (caller, v) the reference reverts on empty _tos, so ok must be false.
        assertTrue(!ok);
    }
}
